import React,{useState,useEffect,useRef} from 'react';import {createRoot} from 'react-dom/client';import TypographyPanel from '../../src/components/TypographyPanel.jsx';import {api} from '../../src/api/client.js';import {composeInvitationPreview} from '../../src/utils/mergePreviewOverride.js';import {mountTypography} from '../../public/templates/shared/typography-runtime.js';
const initial={metricsMode:'template',sections:{bride:{metricsMode:'custom',headingScale:1,bodyScale:1},groom:{metricsMode:'custom',headingScale:1,bodyScale:1}}};
const invitation={id:'qa',themeId:'garden-canvas',themeSettings:{typography:initial},coupleProfile:{brideName:'Test'}};
const staleDraft={themeSettings:{typography:initial},coupleProfile:{brideName:'Unsaved content'}};
api.patch=async(url,payload)=>{await new Promise(r=>setTimeout(r,180));return {data:{themeSettings:{typography:payload.typography}}}};
function App(){const [saved,setSaved]=useState(invitation),[live,setLive]=useState(null),[check,setCheck]=useState('Ready');const root=useRef(null),runtime=useRef(null);const preview=composeInvitationPreview(saved,staleDraft,live);useEffect(()=>{runtime.current=mountTypography(root.current,initial);return()=>runtime.current.destroy()},[]);useEffect(()=>{runtime.current.update(preview.themeSettings.typography);const expected=preview.themeSettings.typography.sections;const items=[...root.current.querySelectorAll('[data-section]')];const ok=items.every(el=>Math.abs(parseFloat(getComputedStyle(el.querySelector('h2')).fontSize)-46*(expected[el.dataset.section]?.headingScale||1))<.01&&Math.abs(parseFloat(getComputedStyle(el.querySelector('p')).fontSize)-11*(expected[el.dataset.section]?.bodyScale||1))<.01);setCheck(`${ok?'PASS':'FAIL'} ${live?'LIVE':'SAVED'} ${items.map(el=>el.dataset.section+': '+getComputedStyle(el.querySelector('h2')).fontSize+' / '+getComputedStyle(el.querySelector('p')).fontSize).join('; ')}; ${preview.coupleProfile.brideName}`)},[saved,live]);return <><pre role="status">{check}</pre><div ref={root}>{['bride','groom'].map(id=><section data-section={id} key={id}><h2 style={{fontSize:46}}>Nama {id}</h2><p style={{fontSize:11}}>Body {id}</p></section>)}</div><TypographyPanel invitation={saved} mode="metrics" scopeOptions={['bride','groom']} activeSection="bride" onUpdated={setSaved} onLivePreview={p=>setLive(p?.themeSettings?.typography||null)}/></>}
createRoot(document.getElementById('root')).render(<App/>);
